-- Guard: manifest surfaces missing a ui_surface row
SELECT s.name FROM (VALUES ('matrx-admin/email'), ('matrx-admin/server-logs'), ('matrx-admin/sandbox')) AS s(name) LEFT JOIN ui.ui_surface u ON u.name = s.name WHERE u.name IS NULL;

-- Upsert all manifest values
ON CONFLICT (surface_name, name) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description, value_type = EXCLUDED.value_type, always_available = EXCLUDED.always_available, typical_char_count = EXCLUDED.typical_char_count, sort_order = EXCLUDED.sort_order, auto_context = EXCLUDED.auto_context, group_key = EXCLUDED.group_key, updated_at = now();

-- Upsert all manifest write targets
ON CONFLICT (surface_name, name) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description, value_type = EXCLUDED.value_type, mode = EXCLUDED.mode, updates_value = EXCLUDED.updates_value, group_key = EXCLUDED.group_key, sort_order = EXCLUDED.sort_order, apply_policy = EXCLUDED.apply_policy, updated_at = now();

-- Mirror url_pattern / intro / parent_surface_name (declared fields only)
UPDATE ui.ui_surface SET label = 'Email Users', value_groups = '[{"key":"recipients","label":"Recipients","sortOrder":100,"description":"Who the email is addressed to: custom typed addresses, or a set of selected platform users."},{"key":"compose","label":"Message","sortOrder":200,"description":"The subject/body being composed, the available templates, and the last send attempt''s outcome."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'verified', readiness_note = NULL, url_pattern = '/administration/users/email', intro = '<surface_intro>
This is an ADMIN surface: the Email Users compose tool at /administration/users/email, for sending a one-off email to either hand-typed addresses or selected platform users.

recipient_mode tells you whether custom_emails_raw or selected_user_ids is the live recipient list. subject and message_body are the draft; available_templates lists quick-start options the admin can pick from. is_sending is true only while a send POST is in flight; last_send_result reflects the LAST attempt only, never anything current or planned.

What you may safely do: help draft or improve subject/message copy, suggest a template, or reason about the selected recipients. The email_draft write target lets you put that copy straight into the form. You never send the email yourself — sending is the admin pressing "Send Email" — and you never choose the recipients or the From address: those have no write target here.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/email';
UPDATE ui.ui_surface SET label = 'Server Logs', value_groups = '[{"key":"app_selection","label":"App selection","sortOrder":100,"description":"Which backend service/environment the viewer is showing, and the catalogue of services it can switch between."},{"key":"fetch_state","label":"Fetch state","sortOrder":200,"description":"How many lines were requested, the auto-poll interval, when the log text was last fetched, and any fetch error."},{"key":"filters","label":"Filters & search","sortOrder":300,"description":"The active level/category/urgency/module/endpoint/search filters, the noise-exclusion presets, and the line-range window applied to the parsed log lines."},{"key":"log_view","label":"Log content","sortOrder":400,"description":"The parsed log lines currently visible after filtering, and the line (or range) the admin has selected for inspection."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'verified', readiness_note = NULL, url_pattern = '/administration/compute/server-logs', intro = '<surface_intro>
This is an ADMIN surface: the super-admin server log viewer at /administration/compute/server-logs/[app], showing live Coolify logs for one backend service (aidream, scraper-service, or matrx-ai, each with a production and development deployment).

The viewer fetches raw log text, parses it into lines with level/category/urgency/module, and lets the admin filter, search, and select a line for JSON-payload inspection. selected_app and selected_app_environment tell you which service/environment you are looking at; log_filters, log_noise_excludes and log_view_range describe what has been narrowed out; fetched_log_line_count vs visible_log_line_count tell you how much of the fetch survived that narrowing.

READ THE LOGS FROM visible_log_lines — it carries the actual text of the lines on screen. visible_log_level_counts answers "is anything erroring" without reading them. selected_log_line and selected_line_range tell you what the admin has singled out; the marked text arrives as the baseline "selection" value. Both visible_log_lines and raw_logs are capped to a TAIL of the newest lines and announce it with a "[truncated: ...]" banner — believe that banner rather than counting lines yourself, and say so when a question depends on lines that were cut.

What you may safely do: read the visible/selected log content and explain errors, summarize patterns, or suggest a better filter or search term. This surface is READ-ONLY BY DESIGN — it declares no write targets, and you cannot change a filter, restart, deploy, or modify the service being logged. The logs are the record of what happened; if you propose a filter or a fix, say it is a suggestion and never imply you applied it.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/server-logs';
UPDATE ui.ui_surface SET label = 'Sandbox Management', value_groups = '[{"key":"fleet_stats","label":"Fleet stats","sortOrder":100,"description":"Summary counts across all sandbox instances currently loaded: active, total, unique users, failed."},{"key":"instance_list","label":"Instance list","sortOrder":200,"description":"The filtered table of sandbox instances, the active status filter, and load/error state."},{"key":"instance_detail","label":"Expanded instance","sortOrder":300,"description":"The single instance row the admin has expanded, if any — its full detail (container, TTL, paths, config)."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'verified', readiness_note = NULL, url_pattern = '/administration/compute/sandbox', intro = '<surface_intro>
This is an ADMIN surface: the super-admin sandbox fleet console at /administration/compute/sandbox — every on-demand isolated agent-execution instance across every user, not just the current admin''s own.

sandbox_active_count / sandbox_total_count / sandbox_unique_user_count / sandbox_failed_count summarize the currently loaded (filtered) set; sandbox_status_filter tells you which status chip is active; sandbox_instances is the actual row data. expanded_sandbox_instance_id is set when the admin has drilled into one row''s full detail, and expanded_sandbox_instance carries that row itself (container id, TTL, hot/cold storage paths, stop reason, last heartbeat, config) — it is the only per-instance data in your automatic context, since sandbox_instances is bindable-only.

What you may safely do: read this fleet data to diagnose stuck/failed instances, summarize usage across users, or explain a status. This surface is READ-ONLY for agents — it declares no write targets, and there is nothing here you can change. Stopping, deleting, or minting SSH access are admin button actions — never assume one happened because it was discussed, and never offer to perform one. SSH credentials are never placed in this surface''s context; they are one-time secret material shown only in the admin''s own dialog.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/sandbox';

